package scram

import "testing"

// Generated by PostgreSQL 16.10: SET password_encryption = 'scram-sha-256';
// CREATE ROLE x PASSWORD 'dev-only-app'; SELECT rolpassword FROM pg_authid WHERE rolname = 'x'.
const pgVerifier = "SCRAM-SHA-256$4096:IT+3mLWfsbG2L6Ib+docLQ==$sX+Us6qa9vACSteoKK8xWJNR1P+LI7UsQCBGPJliGrw=:L5i9+eNdH2ASyF73LwNxvpHszkmBcSBWbW6t2DKaWpQ="

func TestMatchesPostgresVerifier(t *testing.T) {
	t.Parallel()
	if !Matches(pgVerifier, "dev-only-app") {
		t.Fatal("verifier made by PostgreSQL does not match its password")
	}
	if Matches(pgVerifier, "dev-only-ap") {
		t.Fatal("verifier matches the wrong password")
	}
}

func TestEncodeRoundTrip(t *testing.T) {
	t.Parallel()
	v, err := Encode("s3cret-pass")
	if err != nil {
		t.Fatal(err)
	}
	if !Matches(v, "s3cret-pass") || Matches(v, "other") {
		t.Fatalf("round trip failed for %s", v)
	}
	v2, _ := Encode("s3cret-pass")
	if v == v2 {
		t.Fatal("two verifiers share a salt")
	}
}

func TestMatchesRejectsGarbage(t *testing.T) {
	t.Parallel()
	for _, v := range []string{"", "md5abc", "SCRAM-SHA-256$x:y$z:w", "SCRAM-SHA-256$4096:!!$a:b", "SCRAM-SHA-256$0:YQ==$YQ==:YQ=="} {
		if Matches(v, "pw") {
			t.Errorf("Matches(%q) = true", v)
		}
	}
}

func TestCheckPassword(t *testing.T) {
	t.Parallel()
	for _, pw := range []string{"", "tab\there", "naïve"} {
		if CheckPassword(pw) == nil {
			t.Errorf("CheckPassword(%q) = nil", pw)
		}
		if _, err := Encode(pw); err == nil {
			t.Errorf("Encode(%q) succeeded", pw)
		}
	}
}
